package com.projectdark.mobile;
import static org.junit.Assert.*;
import com.projectdark.mobile.world.*;
import java.util.*;
import org.junit.Test;
import org.json.*;
public class CountessCastleV273Test {
 @Test public void allOriginalMapsHaveConnectedSafeSpawnsDistinctGatesAndNativeRosters(){RuntimeState s=new RuntimeState();Set<Integer> types=new HashSet<>();for(String id:CountessCastleData.ids()){assertTrue(CampaignWorld.contains(id));PoteCampaignMapDef d=PoteCampaignMapDef.forId(id);assertEquals(id,d.id);List<WorldMoveTargetController.TileCenter> nav=CountessCastleGeometry.tiles(id,true);assertTrue(id,nav.size()>100);assertSame(nav,CountessCastleGeometry.tiles(id,true));assertTrue(id,d.isNavigationCenter(d.entryX,d.entryY));assertFalse(id,d.terrainBlocked(d.entryX,d.entryY,10));s.enterCampaignMap(id,false);Set<String> seen=new HashSet<>();for(CountessCastleGeometry.Gate gate:CountessCastleGeometry.gates(id)){assertTrue(id,d.isNavigationCenter(gate.x,gate.y));assertTrue(CampaignWorld.contains(gate.to));assertTrue(id,seen.add(gate.x+":"+gate.y));assertTrue(id,Math.hypot(gate.x-s.player().x,gate.y-s.player().y)>60);}for(RuntimeState.Monster m:s.monsters()){types.add(CountessCastleMonsters.type(m.id));assertTrue(d.isNavigationCenter(m.x,m.y));assertFalse(id,s.blocked(m.x,m.y));assertTrue(CountessCastleMonsters.actor(m.id));assertNotNull(AbelCombatProfile.forId(m.id));assertTrue(Float.isInfinite(m.respawnSeconds));}}assertEquals(15,types.size());}
 @Test public void onlyCorrectNpcAtCorrectMapCanAdmitAndGuardIsActuallyCreated(){RuntimeState s=new RuntimeState();s.enterCampaignMap(DeathVillageGeometry.LOBBY,false);RuntimeState.Npc guard=null;for(RuntimeState.Npc n:s.npcs())if(CountessCastleTravel.GUARD.equals(n.id))guard=n;assertNotNull(guard);assertEquals("백작부인별장입장",guard.name);assertFalse(s.blocked(guard.x,guard.y));assertEquals("death-knight",TownServiceArt.role(guard.id));assertEquals(CountessCastleGeometry.EXTERIOR,CountessCastleTravel.destination(s.currentMapId(),guard.id));assertNull(CountessCastleTravel.destination("MILLES",guard.id));s.enterCampaignMap(CountessCastleGeometry.EXTERIOR,false);assertEquals(1,s.npcs().size());assertEquals(CountessCastleTravel.ENVOY,s.npcs().get(0).id);assertEquals(CountessCastleGeometry.UPPER,CountessCastleTravel.destination(s.currentMapId(),s.npcs().get(0).id));}
 @Test public void gateLatchRequiresLeavingArrivalAndEveryRouteCanReturn(){RuntimeState s=new RuntimeState();for(String id:CountessCastleData.ids()){s.enterCampaignMap(id,false);CountessCastleTravel travel=new CountessCastleTravel();travel.arrived(id);assertNull(travel.at(s));CountessCastleGeometry.Gate g=CountessCastleGeometry.gates(id).get(0);s.player().x=g.x;s.player().y=g.y;assertSame(g,travel.at(s));assertNull(travel.at(s));s.player().x=CountessCastleGeometry.entry(id).x;s.player().y=CountessCastleGeometry.entry(id).y;assertNull(travel.at(s));s.player().x=g.x;s.player().y=g.y;assertSame(g,travel.at(s));}}
 @Test public void bossCannotRespawnEarlyRevivesOnceAndBothLivesPersistAcrossMapsAndSnapshot()throws Exception{RuntimeState s=new RuntimeState();String boss=CountessCastleGeometry.BOSS;s.enterCampaignMap(boss,false);RuntimeState.Monster first=null,second=null;for(RuntimeState.Monster m:s.monsters()){if(CountessCastleMonsters.type(m.id)==10)first=m;if(CountessCastleMonsters.type(m.id)==11)second=m;}assertNotNull(first);assertNotNull(second);s.tick(1);assertFalse(second.alive);assertTrue(first.alive);assertEquals(0,CountessCastleMonsters.profile(first.id).exp);s.damage(first,first.maxHp);s.tick(.01f);assertTrue(first.bossRecovered);assertTrue(second.alive);assertFalse(first.alive);s.damage(second,second.maxHp);s.tick(.01f);assertFalse(second.alive);assertFalse(s.countess().revive(s));s.enterCampaignMap(CountessCastleGeometry.UPPER,false);JSONObject snapshot=s.countess().snapshot();RuntimeState restored=new RuntimeState();assertTrue(restored.countess().restore(snapshot));restored.enterCampaignMap(boss,false);for(RuntimeState.Monster m:restored.monsters())if(CountessCastleMonsters.type(m.id)==10||CountessCastleMonsters.type(m.id)==11)assertFalse(m.alive);restored.tick(30);for(RuntimeState.Monster m:restored.monsters())if(CountessCastleMonsters.type(m.id)==11)assertFalse(m.alive);}
 @Test public void narcoliDispelAndSilenceUseSharedResolutionForPlayerAndCompanion(){RuntimeState s=new RuntimeState();s.party().enableTesting(s);s.enterCampaignMap(CountessCastleGeometry.zoneId(3),false);RuntimeState.Monster m=s.monsters().get(0);CompanionParty.Member ally=s.party().active();ally.map=s.currentMapId();RuntimeCombatPortAdapter port=new RuntimeCombatPortAdapter(s,(a,b)->true,(a,b)->true);int hp=s.player().hp;port.applyDamage(m.id,"player","MONSTER_NARCOLI",999);assertEquals(hp,s.player().hp);assertTrue(s.skillEffects().has("player","SLEEP"));s.skillEffects().put(ally.id,"SK_공통_001","PROTECT",1,10);int ahp=ally.body.hp;port.applyDamage(m.id,ally.id,"MONSTER_DISPEL",999);assertEquals(ahp,ally.body.hp);assertFalse(s.skillEffects().has(ally.id,"PROTECT"));assertTrue(s.skillEffects().has(ally.id,"SILENCE"));assertEquals(CombatResolver.RejectReason.CONTROL,port.actionReady(ally.id,ally.id,"SK_성직자_001",true));s.tick(3.1f);assertFalse(s.skillEffects().has(ally.id,"SILENCE"));}
 @Test public void mapSwitchRetainsKillsDamageAndDoesNotMintRewardsTwice(){RuntimeState s=new RuntimeState();String id=CountessCastleGeometry.zoneId(5);s.enterCampaignMap(id,false);RuntimeState.Monster a=s.monsters().get(0),b=s.monsters().get(1);s.damage(a,a.maxHp);s.damage(b,37);int hp=b.hp;long sequence=s.ledger().sequence();s.enterCampaignMap(CountessCastleGeometry.LOBBY,false);s.enterCampaignMap(id,false);assertFalse(s.monsters().get(0).alive);assertEquals(hp,s.monsters().get(1).hp);assertEquals(sequence,s.ledger().sequence());s.tick(60);assertFalse(s.monsters().get(0).alive);}
 @Test public void actualMonsterAiSubmitsNarcoliThroughResolverWithRealManaAndStatus(){RuntimeState s=new RuntimeState();s.enterCampaignMap(CountessCastleGeometry.zoneId(3),false);RuntimeState.Monster m=s.monsters().get(0);s.player().x=m.x+32;s.player().y=m.y+16;int mp=m.mp;RuntimeCombatSession combat=new RuntimeCombatSession(s,(a,b)->true,(a,b)->true,a->true);MonsterAIController ai=new MonsterAIController(new MonsterAIController.SharedResolverAttackRouter(combat.monsterAutoBridge()));boolean seen=false;for(int i=0;i<30;i++){ai.tick(s,.05f);combat.tick(.05f);s.tick(.05f);if(s.skillEffects().has("player","SLEEP"))seen=true;}assertTrue(seen);assertTrue(m.mp<mp);}
 @Test public void dianaSummonsTheSourceBombOnceAndCannotSummonAfterDeath(){RuntimeState s=new RuntimeState();s.enterCampaignMap(CountessCastleGeometry.BOSS,false);RuntimeState.Monster lady=s.monsters().get(2),bomb=s.monsters().get(3);assertEquals(12,CountessCastleMonsters.type(lady.id));assertEquals(13,CountessCastleMonsters.type(bomb.id));assertFalse(bomb.alive);s.damage(lady,lady.maxHp/2+1);s.tick(.01f);assertTrue(lady.bossRecovered);assertTrue(bomb.alive);s.damage(bomb,bomb.maxHp);s.tick(.01f);assertFalse(bomb.alive);s.damage(lady,lady.maxHp);s.tick(.01f);assertFalse(bomb.alive);}

 @Test public void videoReviewSeparatesReceptionRoutesAndChecksEveryZoneRosterAndDoor(){
  assertEquals(CountessCastleGeometry.UPPER,CountessCastleTravel.destination(CountessCastleGeometry.EXTERIOR,CountessCastleTravel.ENVOY));
  assertEquals(CountessCastleGeometry.LOBBY,CountessCastleGeometry.gates(CountessCastleGeometry.EXTERIOR).get(0).to);
  int[][] expected={{0},{0},{1},{4},{2},{2},{3},{5,6,7,8},{5,6,7,8},{9,5,7,8},{9,14,5,7,8},{10,11,12,13,0,1,9}};
  for(int z=1;z<=12;z++){String id=CountessCastleGeometry.zoneId(z);assertEquals("백작부인별장"+z+"존",CampaignWorld.title(id));assertArrayEquals(expected[z-1],CountessCastleMonsters.roster(id));for(CountessCastleGeometry.Gate g:CountessCastleGeometry.gates(id))assertEquals(CountessCastleGeometry.title(g.to),g.label);
   if(z<12){CountessCastleGeometry.Gate next=CountessCastleGeometry.gates(id).get(1);assertEquals(CountessCastleGeometry.zoneId(z+1),next.to);assertEquals(z==6?0:z==8?29:13,CountessCastleGeometry.u(next.x,next.y));assertEquals(z==6?14:z==8?13:0,CountessCastleGeometry.v(next.x,next.y));}
  }
 }
}
